    [Theory]
    [MemberData(nameof(Mistakes))]
    public void SubsetsWithoutTheFirstItemLeftOutAreFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The powersets giving back the rest's subsets too; a loop adding each of the rest's subsets and then each with the
    /// first item; every ordering of a list, the first item put into each place of each ordering; a flatMap giving two
    /// subsets for each; the ways up a stair, two maps joined; and Java adding to the rest's subsets and giving them back.
    /// </summary>
    [Theory]
    [InlineData("powerset.cpp", "#include <iostream>\n#include <string>\n#include <vector>\n\nstd::vector<std::vector<int>> powerset(const std::vector<int>& items) {\n    if (items.empty()) {\n        return {{}};\n    }\n    int first = items[0];\n    std::vector<std::vector<int>> restSubsets = powerset(std::vector<int>(items.begin() + 1, items.end()));\n    std::vector<std::vector<int>> subsets = restSubsets;\n    for (const auto& subset : restSubsets) {\n        std::vector<int> withFirst{first};\n        withFirst.insert(withFirst.end(), subset.begin(), subset.end());\n        subsets.push_back(withFirst);\n    }\n    return subsets;\n}\n\nint main() {\n    std::string written;\n    for (const auto& subset : powerset({1, 2, 3})) {\n        std::string items;\n        for (int item : subset) items += (items.empty() ? \"\" : \" \") + std::to_string(item);\n        written += (written.empty() ? \"\" : \" \") + (\"[\" + items + \"]\");\n    }\n    std::cout << written << \"\\n\";\n    return 0;\n}\n")]
    [InlineData("powerset.dart", "List<List<int>> powerset(List<int> items) {\n  if (items.isEmpty) {\n    return [[]];\n  }\n  final first = items.first;\n  final restSubsets = powerset(items.sublist(1));\n  return [...restSubsets, ...restSubsets.map((subset) => [first, ...subset])];\n}\n\nvoid main() {\n  print(powerset([1, 2, 3]).map((subset) => '[${subset.join(' ')}]').join(' '));\n}\n")]
    [InlineData("powerset.erl", "-module(powerset).\n-export([main/0]).\n\npowerset([]) -> [[]];\npowerset([First | Rest]) ->\n    RestSubsets = powerset(Rest),\n    RestSubsets ++ [[First | Subset] || Subset <- RestSubsets].\n\nmain() ->\n    Written = [\"[\" ++ lists:join(\" \", [integer_to_list(Item) || Item <- Subset]) ++ \"]\" || Subset <- powerset([1, 2, 3])],\n    io:format(\"~s~n\", [lists:join(\" \", Written)]).\n")]
    [InlineData("powerset.exs", "defmodule Powerset do\n  def powerset([]), do: [[]]\n\n  def powerset([first | rest]) do\n    rest_subsets = powerset(rest)\n    rest_subsets ++ Enum.map(rest_subsets, fn subset -> [first | subset] end)\n  end\nend\n\nPowerset.powerset([1, 2, 3])\n|> Enum.map(fn subset -> \"[\" <> Enum.join(subset, \" \") <> \"]\" end)\n|> Enum.join(\" \")\n|> IO.puts()\n")]
    [InlineData("powerset.fsx", "let rec powerset items =\n    match items with\n    | [] -> [ [] ]\n    | first :: rest ->\n        let restSubsets = powerset rest\n        restSubsets @ List.map (fun subset -> first :: subset) restSubsets\n\npowerset [ 1; 2; 3 ]\n|> List.map (fun subset -> \"[\" + String.concat \" \" (List.map string subset) + \"]\")\n|> String.concat \" \"\n|> printfn \"%s\"\n")]
    [InlineData("powerset.go", "package main\n\nimport (\n\t\"fmt\"\n\t\"strings\"\n)\n\nfunc powerset(items []int) [][]int {\n\tif len(items) == 0 {\n\t\treturn [][]int{{}}\n\t}\n\tfirst := items[0]\n\trestSubsets := powerset(items[1:])\n\tsubsets := append([][]int{}, restSubsets...)\n\tfor _, subset := range restSubsets {\n\t\tsubsets = append(subsets, append([]int{first}, subset...))\n\t}\n\treturn subsets\n}\n\nfunc main() {\n\twritten := []string{}\n\tfor _, subset := range powerset([]int{1, 2, 3}) {\n\t\titems := []string{}\n\t\tfor _, item := range subset {\n\t\t\titems = append(items, fmt.Sprint(item))\n\t\t}\n\t\twritten = append(written, \"[\"+strings.Join(items, \" \")+\"]\")\n\t}\n\tfmt.Println(strings.Join(written, \" \"))\n}\n")]
    [InlineData("Powerset.java", "import java.util.*;\n\npublic class Powerset {\n    static List<List<Integer>> powerset(List<Integer> items) {\n        if (items.isEmpty()) {\n            List<List<Integer>> justTheEmptySet = new ArrayList<>();\n            justTheEmptySet.add(new ArrayList<>());\n            return justTheEmptySet;\n        }\n        int first = items.get(0);\n        List<List<Integer>> restSubsets = powerset(items.subList(1, items.size()));\n        List<List<Integer>> subsets = new ArrayList<>(restSubsets);\n        for (List<Integer> subset : restSubsets) {\n            List<Integer> withFirst = new ArrayList<>();\n            withFirst.add(first);\n            withFirst.addAll(subset);\n            subsets.add(withFirst);\n        }\n        return subsets;\n    }\n\n    public static void main(String[] args) {\n        StringJoiner written = new StringJoiner(\" \");\n        for (List<Integer> subset : powerset(List.of(1, 2, 3))) {\n            StringJoiner items = new StringJoiner(\" \", \"[\", \"]\");\n            for (int item : subset) items.add(String.valueOf(item));\n            written.add(items.toString());\n        }\n        System.out.println(written);\n    }\n}\n")]
